import{_ as r,a0 as l,w as p,s as a,ao as d,I as o,x as n,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux 服務器管理員的12個有用的命令 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 服務器管理員的12個有用的命令 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 服務器管理員的12個有用的命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 服務器管理員的12個有用的命令 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/12 Advanced Commands For Linux Server Admins!","title":"Linux 服務器管理員的12個有用的命令","tag":"201401","desc":""},"relativePath":"201401/12 Advanced Commands For Linux Server Admins!.md","filePath":"[post].md"}'),m={name:"201401/12 Advanced Commands For Linux Server Admins!.md"};function g(u,t,f,x,L,T){const e=l("Link");return p(),a("div",null,[t[11]||(t[11]=d('<h1 id="linux-服務器管理員的12個有用的命令" tabindex="-1">Linux 服務器管理員的12個有用的命令 <a class="header-anchor" href="#linux-服務器管理員的12個有用的命令" aria-label="Permalink to “Linux 服務器管理員的12個有用的命令”">​</a></h1><p>我們已經讀了很多教程和看了很多視頻了，你現在是一名Linux高級用户了。好的，恭喜你。但是還有一些需要學習！下面一些命令在你成為全能的管理員時會派上用場！</p><p><img src="http://www.efytimes.com/admin/useradmin/photo/fQjv122633PM162014.png" alt=""></p><ol><li><p><strong>ifconfig</strong>: 在修改內核中已有的網絡接口時，你會用到ifconfig命令。這個命令通常用於系統調校和調試，但同時也可以用於在啓動過程中設置接口。</p></li><li><p><strong>netstat</strong>: 對於Linux用户來説這是一個用於顯示網絡相關信息的高級命令。它包括路由表、網絡連接、偽裝連接、接口統計等豐富信息。</p></li><li><p><strong>nslookup</strong>: 在你需要找出關於網絡服務的信息時可以用到這個命令。它能幫你找到用於查詢DNS域的名稱服務器信息。</p></li><li><p><strong>dig</strong>: dig工具用於請求DNS域名服務器。如果你要找出主機地址、郵件交換、名稱服務器和其他相關信息，那麼這個工具就是最佳選擇。你可以在Linux和Mac OS X操作系統上使用這個命令。</p></li><li><p><strong>uptime</strong>: uptime命令用於驗證服務器在無人照看下發生了什麼。當你需要坐在服務器前查找錯誤的時候，這個命令尤其有用。</p></li><li><p><strong>wall</strong>: 這個命令用於給所有已登錄的用户發送消息。你可以只給那些消息權限設置成了&#39;是&#39;的用户發消息。消息是作為wall命令的參數給出的。</p></li><li><p><strong>mesg</strong>: 用户可以使用&#39;write&#39;命令給你發送消息。但是作為服務器管理員，你可以使用mesg命令來決定他們是否能夠使用write命令。你可以選擇&#39;n&#39;和&#39;y&#39;，分別用於控制在屏幕上不彈出或者彈出消息。</p></li><li><p><strong>write</strong>: 如果對於一個用户的&#39;mesg&#39;命令的狀態設置為&#39;y&#39;，那麼write命令就允許你發送消息給那個用户。</p></li><li><p><strong>talk</strong>: 當上面所説的“消息”不夠用時，使用talk命令與登陸的用户進行“會話”。</p></li><li><p><strong>w</strong>: 這個命令是uptime和who命令的結合，其顯示結果就好像連續先後執行了這兩個命令一樣。</p></li><li><p><strong>rename</strong>:當你需要重命名特定的文件時，rename命令會派上用場。這個命令可以通過匹配替換來為多個文件批量重命名。</p></li><li><p><strong>top</strong>:這個命令可以顯示運行在CPU上的進程。命令會自動刷新並持續顯示進程直到你使用中斷命令停止它。</p></li></ol><hr>',5)),o("p",null,[t[1]||(t[1]=n("via: ",-1)),i(e,{href:"http://www.efytimes.com/e1/fullnews.asp?edid=125990"},{default:s(()=>[...t[0]||(t[0]=[n("http://www.efytimes.com/e1/fullnews.asp?edid=125990",-1)])]),_:1})]),o("p",null,[t[4]||(t[4]=n("譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[2]||(t[2]=[n("geekpi",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),i(e,{href:"http://blog.csdn.net/tinyeyeser"},{default:s(()=>[...t[3]||(t[3]=[n("Mr小眼兒",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const v=r(m,[["render",g]]);export{_ as __pageData,v as default};
